import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  Checkbox,
  CircularProgress,
  FormControl,
  FormHelperText,
  Grid,
  ListItemText,
  MenuItem,
  OutlinedInput,
  Select,
  SelectChangeEvent,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import PersonOutlinedIcon from '@mui/icons-material/PersonOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useGetAllUserPrivilegesQuery, useNewUserMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import * as Yup from 'yup';
import {
  IUserDetailsData,
  IPrivileges,
} from '../../../core/Interface/user.interface';
import { useMemo } from 'react';
import InputAdornment from '@mui/material/InputAdornment';
import IconButton from '@mui/material/IconButton';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import SearchIcon from '@mui/icons-material/Search';
import { uploadImage } from '../../../core/utils';

interface INewUser {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: IUserDetailsData;
  isImageEnabled: boolean;
}

const NewUser = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
  isImageEnabled,
}: INewUser) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newUser, { isLoading }] = useNewUserMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'usermanage']);
  const [showPassword, setShowPassword] = React.useState(false);
  const buttonText = data ? t('common:update') : t('common:create');
  const [privilegeSearchText, setPrivilegeSearchText] = React.useState('');

  const { data: privilegeData } =
    useGetAllUserPrivilegesQuery();

  const [privilegesList] = React.useState<IPrivileges[]>(
    data ? data.privileges : []
  );

  const [privilegeIds, setPrivilegeIds] = React.useState<number[]>(
    privilegesList
      ? privilegesList.map((privileges) => privileges.privilege)
      : []
  );

  const filteredPrivileges = useMemo(() => {
    if (!privilegeData?.data) return [];
    const privileges = privilegeData.data as { key: string; value: number }[];
    return privileges.filter((privilege) =>
      privilege.key.toLowerCase().includes(privilegeSearchText.toLowerCase())
    );
  }, [privilegeData, privilegeSearchText]);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const handleChange = (event: SelectChangeEvent<typeof privilegeIds>) => {
    const {
      target: { value },
    } = event;

    // const allPrivileges =
    //   (privilegeData?.data as { key: string; value: number }[]) || [];

    const allPrivileges = filteredPrivileges;
    const allIds = allPrivileges.map((p) => p.value);
    const selected = value as number[];

    if (selected.includes(-1)) {
      const isAllSelected = privilegeIds.length === allIds.length;
      const newSelected = isAllSelected ? [] : allIds;

      setPrivilegeIds(newSelected);
      formik.setFieldValue('privileges', newSelected);
    } else {
      setPrivilegeIds(selected);
      formik.setFieldValue('privileges', selected);
    }
  };

  const handlePrivilegeSearchChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    setPrivilegeSearchText(event.target.value);
  };

  const [selectedImage, setSelectedImage] = React.useState<File | undefined>(
    undefined
  );
  const [isImageUploading, setIsImageUploading] = React.useState(false);

  const validationSchema = Yup.object({
    //  username: Yup.string().required('Username cannot be empty or contain only spaces'),
    email: Yup.string()
      .email('Invalid email address')
      .required('Email is required'),
  });
  const validateName = (value: string) => {
    return /\S/.test(value);
  };
  const validateEmail = (value: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(value);
  };

  const validateMobileNumber = (value: string) => {
    if (value.startsWith('0')) {
      const mobileRegex = /^[0-9]{10}$/;
      return mobileRegex.test(value);
    } else {
      const mobileRegex = /^[1-9]{9}$/;
      return mobileRegex.test(value);
    }
  };

  const formik = useFormik({
    initialValues: {
      firstname: data?.firstname,
      lastname: data?.lastname,
      username: data?.username,
      password: data?.password || '',
      email: data?.email || '',
      mobile: data?.mobile,
      id: data?.id,
      privileges: data?.privileges.map((item) => item.privilege) || [],
      imageUrl: data?.imageUrl,
    },

    validationSchema: validationSchema,
    onSubmit: async (values) => {
      try {
        const formData = new FormData();
        let imageUrl: string | undefined = data?.imageUrl;

        if (selectedImage) {
          setIsImageUploading(true);
          formData.append('imageUrl', selectedImage);
          imageUrl = (await uploadImage(selectedImage)) || '';
          setIsImageUploading(false);
        }
        if (!validateName(values.firstname || '')) {
          showErrorMessage('name cannot be empty or contain only spaces ');
          return;
        }
        if (!validateName(values.lastname || '')) {
          showErrorMessage('name cannot be empty or contain only spaces. ');
          return;
        }
        if (!validateEmail(values.email || '')) {
          showErrorMessage('Please enter a valid email address.');
          return;
        }

        if (!validateMobileNumber(values.mobile || '')) {
          showErrorMessage('Mobile number should be valid.');
          return;
        }

        if (privilegeIds.length === 0) {
          showErrorMessage('Please select at least one privilege.');
          return;
        }

        //values.privileges = privilegesList || [];
        values.imageUrl = imageUrl;

        if (!data) {
          delete values.id;
        }

        const addUserResponse = await newUser(values).unwrap();
        if (!addUserResponse.status) {
          showErrorMessage(addUserResponse.message);
        } else {
          showMessage(addUserResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(() => {
    return formik.values.firstname === '' ||
      formik.values.firstname === undefined ||
      formik.values.lastname === '' ||
      formik.values.lastname === undefined ||
      formik.values.username === '' ||
      formik.values.username === undefined ||
      (data
        ? false
        : formik.values.password === '' ||
          formik.values.password === undefined) ||
      formik.values.email === '' ||
      formik.values.email === undefined ||
      formik.values.mobile === '' ||
      formik.values.mobile === undefined ||
      privilegeIds.length === 0
      ? false
      : true;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formik]);

  const handleImageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files?.[0];

    if (files) {
      const file = files;
      setSelectedImage(file);
    } else {
      setSelectedImage(undefined);
    }
  };

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="sm"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <PersonOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Manage user account</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={t('usermanage:title.firstname')} />
                  <TextField
                    autoComplete="off"
                    placeholder="First Name"
                    size="small"
                    {...formik.getFieldProps('firstname')}
                    error={
                      formik.touched.firstname &&
                      !validateName(formik.values.firstname || '')
                    }
                    helperText={
                      formik.touched.firstname &&
                      !validateName(formik.values.firstname || '') && (
                        <span style={{ textTransform: 'none' }}>
                          name cannot be empty or contain only spaces.
                        </span>
                      )
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('usermanage:title.lastname')} />
                  <TextField
                    autoComplete="off"
                    placeholder="Last Name"
                    size="small"
                    {...formik.getFieldProps('lastname')}
                    error={
                      formik.touched.lastname &&
                      !validateName(formik.values.lastname || '')
                    }
                    helperText={
                      formik.touched.lastname &&
                      !validateName(formik.values.lastname || '') && (
                        <span style={{ textTransform: 'none' }}>
                          name cannot be empty or contain only spaces.
                        </span>
                      )
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('usermanage:title.username')} />
                  <TextField
                    autoComplete="off"
                    inputProps={{ autoComplete: 'new-username' }}
                    placeholder="User Name"
                    size="small"
                    {...formik.getFieldProps('username')}
                    disabled={!!data}
                    error={
                      (formik.touched.username && !!formik.errors.username) ||
                      (formik.values.username ?? '').trim() === ''
                    }
                    helperText={
                      (formik.touched.username && !!formik.errors.username) ||
                      (formik.values.username ?? '').trim() === '' ? (
                        <span style={{ textTransform: 'none' }}>
                          {formik.errors.username ||
                            'Username cannot be empty or contain only spaces.'}
                        </span>
                      ) : null
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                {!data && (
                  <GridItem sx={{ pt: 2 }}>
                    <FieldHeader title="Password" />
                    <TextField
                      autoComplete="off"
                      inputProps={{ autoComplete: 'new-password' }}
                      placeholder="Password"
                      size="small"
                      type={showPassword ? 'text' : 'password'}
                      {...formik.getFieldProps('password')}
                      InputProps={{
                        endAdornment: (
                          <InputAdornment position="end">
                            <IconButton
                              edge="end"
                              onClick={() => setShowPassword(!showPassword)}
                            >
                              {showPassword ? (
                                <VisibilityOff />
                              ) : (
                                <Visibility />
                              )}
                            </IconButton>
                          </InputAdornment>
                        ),
                      }}
                      sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    />
                  </GridItem>
                )}
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('usermanage:title.email')} />
                  <TextField
                    autoComplete="off"
                    placeholder="Email"
                    size="small"
                    {...formik.getFieldProps('email')}
                    error={
                      formik.touched.email &&
                      (!validateEmail(formik.values.email || '') ||
                        formik.values.email?.length === 0)
                    }
                    helperText={
                      formik.touched.email &&
                      (!validateEmail(formik.values.email || '') ||
                        formik.values.email?.length === 0) && (
                        <span style={{ textTransform: 'none' }}>
                          Please enter valid email id.
                        </span>
                      )
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('usermanage:title.mobile')} />
                  <TextField
                    autoComplete="off"
                    placeholder="Mobile"
                    size="small"
                    {...formik.getFieldProps('mobile')}
                    error={
                      formik.touched.mobile &&
                      !validateMobileNumber(formik.values.mobile || '')
                    }
                    helperText={
                      formik.touched.mobile &&
                      !validateMobileNumber(formik.values.mobile || '') && (
                        <span style={{ textTransform: 'none' }}>
                          Please enter valid mobile number.
                        </span>
                      )
                    }
                    inputProps={{
                      maxLength: 10,
                      type: 'tel',
                    }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('usermanage:title.privileges')} />
                  <FormControl error={privilegeIds.length === 0} sx={{ width: '100%' }}>
                    <Select
                      input={
                        <OutlinedInput
                          sx={{
                            height: `${theme.spacing(5)}`,
                            fontSize: 13,
                            ...(privilegeIds.length === 0 && { '& fieldset': { borderColor: '#d32f2f' } }),
                          }}
                        />
                      }
                      MenuProps={{
                        PaperProps: {
                          sx: {
                            borderRadius: '10px',
                            border: '1px solid #E2E8F0',
                            boxShadow: '0 8px 32px rgba(15,29,77,0.12)',
                            mt: 0.5,
                            maxHeight: 380,
                            '& .MuiList-root': { py: 0 },
                            '&::-webkit-scrollbar': { width: 5 },
                            '&::-webkit-scrollbar-track': { background: '#F8FAFC' },
                            '&::-webkit-scrollbar-thumb': { background: '#CBD5E1', borderRadius: 10 },
                          },
                        },
                        autoFocus: false,
                      }}
                      multiple
                      onChange={handleChange}
                      renderValue={(selected) =>
                        selected.length === 0 ? (
                          <em style={{ color: '#d32f2f', fontStyle: 'normal', fontSize: '0.85rem' }}>
                            Select at least one privilege
                          </em>
                        ) : (
                          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                            <Box
                              sx={{
                                background: 'linear-gradient(135deg, #2563EB, #1d4ed8)',
                                borderRadius: '5px',
                                color: '#fff',
                                fontSize: 11,
                                fontWeight: 700,
                                lineHeight: 1,
                                px: 0.9,
                                py: 0.4,
                              }}
                            >
                              {selected.length}
                            </Box>
                            <span style={{ color: '#374151', fontSize: 13 }}>
                              of {((privilegeData?.data as object[]) ?? []).length} selected
                            </span>
                          </Box>
                        )
                      }
                      value={privilegeIds}
                    >
                      {/* Sticky search bar */}
                      <MenuItem
                        disableRipple
                        sx={{
                          position: 'sticky',
                          top: 0,
                          zIndex: 2,
                          background: '#F8FAFC',
                          borderBottom: '1px solid #E2E8F0',
                          px: 1.5,
                          py: 1,
                          '&:hover': { background: '#F8FAFC' },
                          cursor: 'default',
                        }}
                        value=""
                      >
                        <TextField
                          InputProps={{
                            startAdornment: (
                              <InputAdornment position="start">
                                <SearchIcon sx={{ color: '#94A3B8', fontSize: 17 }} />
                              </InputAdornment>
                            ),
                            endAdornment: privilegeSearchText ? (
                              <InputAdornment position="end">
                                <Box
                                  onClick={(e) => { e.stopPropagation(); setPrivilegeSearchText(''); }}
                                  sx={{ color: '#94A3B8', cursor: 'pointer', fontSize: 13, lineHeight: 1, '&:hover': { color: '#475569' } }}
                                >
                                  ✕
                                </Box>
                              </InputAdornment>
                            ) : null,
                          }}
                          autoComplete="off"
                          onChange={handlePrivilegeSearchChange}
                          onClick={(e) => e.stopPropagation()}
                          onKeyDown={(e) => e.stopPropagation()}
                          placeholder="Search privileges…"
                          size="small"
                          sx={{
                            width: '100%',
                            '& .MuiOutlinedInput-root': {
                              borderRadius: '8px',
                              fontSize: 13,
                              background: '#fff',
                              '& fieldset': { borderColor: '#E2E8F0' },
                              '&:hover fieldset': { borderColor: '#94A3B8' },
                              '&.Mui-focused fieldset': { borderColor: '#2563EB', borderWidth: 1.5 },
                            },
                            '& .MuiInputAdornment-root': { color: '#94A3B8' },
                          }}
                          value={privilegeSearchText}
                          variant="outlined"
                        />
                      </MenuItem>

                      {/* Select All */}
                      <MenuItem
                        sx={{
                          alignItems: 'center',
                          background: '#F8FAFC',
                          borderBottom: '1px solid #E2E8F0',
                          borderLeft: '3px solid transparent',
                          gap: 1,
                          px: 1.5,
                          py: 0.75,
                          '&:hover': { background: '#EFF6FF', borderLeftColor: '#2563EB' },
                          '&.Mui-selected': { background: '#EFF6FF', borderLeftColor: '#2563EB' },
                        }}
                        value={-1}
                      >
                        <Checkbox
                          checked={privilegeIds.length === filteredPrivileges.length && filteredPrivileges.length > 0}
                          indeterminate={privilegeIds.length > 0 && privilegeIds.length < filteredPrivileges.length}
                          size="small"
                          sx={{
                            p: 0.25,
                            color: '#CBD5E1',
                            '&.Mui-checked, &.MuiCheckbox-indeterminate': { color: '#2563EB' },
                          }}
                        />
                        <ListItemText
                          primary="Select All"
                          primaryTypographyProps={{ fontSize: 13, fontWeight: 700, color: '#0F1D4D' }}
                        />
                        <Box sx={{ color: '#64748B', fontSize: 11, ml: 'auto' }}>
                          {privilegeIds.length}/{filteredPrivileges.length}
                        </Box>
                      </MenuItem>

                      {/* Privilege items */}
                      {filteredPrivileges.map((d) => {
                        const isChecked = privilegeIds.indexOf(d.value) > -1;
                        return (
                          <MenuItem
                            key={d.key}
                            sx={{
                              alignItems: 'center',
                              borderLeft: `3px solid ${isChecked ? '#2563EB' : 'transparent'}`,
                              gap: 1,
                              px: 1.5,
                              py: 0.625,
                              transition: 'all 0.1s',
                              background: isChecked ? '#EFF6FF' : 'transparent',
                              '&:hover': {
                                background: isChecked ? '#DBEAFE' : '#F8FAFC',
                                borderLeftColor: '#2563EB',
                              },
                            }}
                            value={d.value}
                          >
                            <Checkbox
                              checked={isChecked}
                              size="small"
                              sx={{
                                p: 0.25,
                                color: '#CBD5E1',
                                '&.Mui-checked': { color: '#2563EB' },
                              }}
                            />
                            <ListItemText
                              primary={d.key}
                              primaryTypographyProps={{
                                fontSize: 13,
                                fontWeight: isChecked ? 600 : 400,
                                color: isChecked ? '#1e3a8a' : '#374151',
                              }}
                            />
                          </MenuItem>
                        );
                      })}

                      {filteredPrivileges.length === 0 && (
                        <MenuItem disabled sx={{ justifyContent: 'center', py: 3 }}>
                          <span style={{ color: '#94A3B8', fontSize: 13 }}>No privileges match</span>
                        </MenuItem>
                      )}
                    </Select>
                    {privilegeIds.length === 0 && (
                      <FormHelperText>At least one privilege must be selected.</FormHelperText>
                    )}
                  </FormControl>
                </GridItem>
                {isImageEnabled && (
                  <GridItem sx={{ pt: 2 }}>
                    <FieldHeader title={t('usermanage:title.upload image')} />
                    <FormControl sx={{ width: '100%' }}>
                      <Box
                        sx={{
                          border: '2px dashed #cccccc',
                          borderRadius: '8px',
                          padding: '16px',
                          display: 'flex',
                          flexDirection: 'column',
                          alignItems: 'center',
                          justifyContent: 'center',
                          height: '200px',
                        }}
                      >
                        <Grid
                          container
                          spacing={2}
                        >
                          <Grid
                            item
                            xs={8}
                          >
                            {selectedImage && (
                              <img
                                alt="Selected"
                                height="160px"
                                src={URL.createObjectURL(selectedImage)}
                                style={{ position: 'inherit' }}
                                width="80%"
                              />
                            )}
                            {!selectedImage && data && (
                              <img
                                alt="Selected"
                                height="160px"
                                src={data.imageUrl}
                                style={{ position: 'inherit' }}
                                width="80%"
                              />
                            )}
                          </Grid>
                          <Grid
                            item
                            xs={4}
                          >
                            <TextField
                              onChange={handleImageChange}
                              type="file"
                            />
                            {isImageUploading && (
                              <Box sx={{ pr: 2, pt: 0.5 }}>
                                <CircularProgress
                                  size={16}
                                  sx={{ color: 'white' }}
                                />
                              </Box>
                            )}
                          </Grid>
                        </Grid>
                      </Box>
                    </FormControl>
                  </GridItem>
                )}
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading}
              onClick={() => { formik.handleSubmit(); }}
              sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
              type="submit"
              variant="contained"
            >
              {isLoading ? <CircularProgress size={16} sx={{ color: '#fff' }} /> : buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewUser);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
