import React, { useCallback, useEffect, useState, useMemo } from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  InputAdornment,
  MenuItem,
  Paper,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import usePageQuery from '../../core/hooks/usePageQuery';
import { Table } from '@tanstack/react-table';
import ReactTable from '../../components/Table/ReactTable';
import PosTablePagination from '../../components/Table/PosTablePagination';
import {
  useDeleteUserManageMutation,
  useGetAllBranchQuery,
  useGetUserQuery,
} from '../posApi';
import { IBranchDetails } from '../../core/Interface/branch.interface';
import { useTranslation } from 'react-i18next';
import {
  IUserDetailsData,
  IPrivileges,
} from '../../core/Interface/user.interface';
import useUserList from './useUserList';
import NewUserManage from './components/NewUser';
import AnimatedPage from '../../layouts/AnimatedPage';
import AddIcon from '@mui/icons-material/Add';
import PeopleAltOutlinedIcon from '@mui/icons-material/PeopleAltOutlined';
import SearchIcon from '@mui/icons-material/Search';
import StoreIcon from '@mui/icons-material/Store';
import ResetPasswordPopup from './components/ResetPasswordPopup';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import { useNotifier } from '../../core/Notifier';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import ViewUserDetails from './components/ViewUserDetails';
import PrivilegesDialog from './components/Privileges';
import UserCard from './components/UserCard';
import { HEADER_GRADIENT } from '../../theme/appColors';

const UserList = () => {
  const { setPage } = usePageQuery();
  const { t } = useTranslation(['common', 'usermanage']);
  const [userDetails, setUserDetails] = React.useState<IUserDetailsData>();
  const [userManageData, setUserManageData] = React.useState<IUserDetailsData | undefined>();
  const [openAddUserManage, setOpenAddUserManage] = useState(false);
  const [openDeleteUserManage, setOpenDeleteUserManage] = useState(false);
  const [openUserManageResetPassword, setOpenUserManageResetPassword] = useState(false);
  const [userManageNameToDelete, setuserManageNameToDelete] = useState<string | null>(null);
  const [userToDelete, setUserToDelete] = useState<IUserDetailsData | null>(null);
  const { showErrorMessage, showMessage } = useNotifier();
  const [openViewUser, setOpenViewUser] = useState(false);
  const [openPrivilege, setOpenPrivilege] = useState(false);
  const [localSearch, setLocalSearch] = useState('');
  const [userPrivilegeData, setUserPrivilegeData] = React.useState<IPrivileges[]>();

  const { data: companyData } = useGetUserQuery();
  const { data: branchData } = useGetAllBranchQuery({
    pageIndex: 0,
    pageSize: 100,
    searchText: '',
  });
  const branches = useMemo(
    () => (branchData?.data as IBranchDetails | undefined)?.records ?? [],
    [branchData]
  );
  const { userHasRight } = useUser();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const isImageEnabled = useMemo(() => {
    type WithImage = { company?: { isImageEnabled?: boolean } };
    const raw = companyData?.data as WithImage | undefined;
    return raw?.company?.isImageEnabled ?? false;
  }, [companyData]);

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleEdit = useCallback((data: IUserDetailsData) => {
    setUserManageData(data);
    setOpenAddUserManage(true);
  }, []);

  const handlePrivilegeData = useCallback((data: IPrivileges[]) => {
    setUserPrivilegeData(data);
    setOpenPrivilege(true);
  }, []);

  const handleResetPassword = useCallback((data: IUserDetailsData) => {
    setUserManageData(data);
    setOpenUserManageResetPassword(true);
  }, []);

  const [deleteUserManage] = useDeleteUserManageMutation();

  const handleDelete = useCallback((data: IUserDetailsData) => {
    setUserToDelete(data);
    setOpenDeleteUserManage(true);
    setuserManageNameToDelete(data.username);
  }, []);

  const handleConfirmDelete = useCallback(async () => {
    if (!userToDelete) return;
    try {
      const response = await deleteUserManage(userToDelete.id.toString()).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteUserManage(false);
        setUserToDelete(null);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  }, [userToDelete, deleteUserManage, showMessage, showErrorMessage]);

  const viewUserDetailsPopUp = useCallback((id: string) => {
    const selectedUser = table.getRowModel().rows.map((r) => r.original).find((u) => u.id === id);
    if (selectedUser) { setUserDetails(selectedUser); setOpenViewUser(true); }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const { table, isLoading, totalCount, popUpUserId, setSearchText, branchId, setBranchId } =
    useUserList(
      handleEdit,
      handleResetPassword,
      handleDelete,
      viewUserDetailsPopUp,
      handlePrivilegeData,
      handlePaginationChangePage
    );

  useEffect(() => {
    if (popUpUserId) setOpenViewUser(true);
  }, [popUpUserId]);

  useEffect(() => {
    if (!isLoading && table.getState().pagination.pageIndex !== 0 && table.getRowModel().rows.length === 0) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  return (
    <AnimatedPage>
      <Box data-testid="user-management">
        {/* Hero Panel */}
        <Paper
          elevation={0}
          sx={{ background: HEADER_GRADIENT, borderRadius: 2, mb: 2, overflow: 'hidden' }}
        >
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexWrap: 'wrap',
              gap: 2,
              justifyContent: 'space-between',
              px: { xs: 2, sm: 3 },
              py: 2,
            }}
          >
            {/* Title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, minWidth: 0 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: 'rgba(255,255,255,0.15)',
                  flexShrink: 0,
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <PeopleAltOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>
                  User Management
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
                  All users
                </Typography>
              </Box>
              {totalCount > 0 && (
                <Chip
                  label={`${totalCount} records`}
                  size="small"
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: '#fff',
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
              )}
            </Box>

            {/* Search + Add */}
            <Box
              sx={{
                alignItems: 'center',
                display: 'flex',
                flexWrap: { xs: 'wrap', md: 'nowrap' },
                gap: '10px',
                width: { xs: '100%', md: 'auto' },
              }}
            >
              {branches.length > 1 && (
                <TextField
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <StoreIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                      </InputAdornment>
                    ),
                  }}
                  SelectProps={{ displayEmpty: true }}
                  onChange={(e) => setBranchId(e.target.value)}
                  select
                  size="small"
                  sx={{
                    minWidth: 180,
                    width: { xs: '100%', sm: 'auto' },
                    '& .MuiOutlinedInput-root': {
                      background: 'rgba(255,255,255,0.12)',
                      borderRadius: '8px',
                      color: '#fff',
                      height: 40,
                      '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                      '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                      '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    },
                    '& .MuiSelect-icon': { color: 'rgba(255,255,255,0.7)' },
                  }}
                  value={branchId}
                >
                  <MenuItem value="">All branches</MenuItem>
                  {branches.map((branch) => (
                    <MenuItem
                      key={branch.id}
                      value={branch.id}
                    >
                      {branch.name}
                    </MenuItem>
                  ))}
                </TextField>
              )}
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setLocalSearch(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') setSearchText(localSearch); }}
                placeholder="Search by username…"
                size="small"
                sx={{
                  flex: { xs: 1, md: 'none' },
                  minWidth: { xs: 0, md: 260 },
                  '& .MuiOutlinedInput-root': {
                    background: 'rgba(255,255,255,0.12)',
                    borderRadius: '8px',
                    color: '#fff',
                    height: 40,
                    '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                  },
                }}
                value={localSearch}
                variant="outlined"
              />
              <Button
                onClick={() => setSearchText(localSearch)}
                sx={{
                  background: 'rgba(255,255,255,0.15)',
                  border: '1px solid rgba(255,255,255,0.3)',
                  borderRadius: '8px',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 600,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'rgba(255,255,255,0.25)' },
                }}
                variant="contained"
              >
                {t('common:search')}
              </Button>

              {userHasRight(Privileges.UserManageAdd) && (
                <Button
                  onClick={() => { setUserManageData(undefined); setOpenAddUserManage(true); }}
                  startIcon={<AddIcon />}
                  sx={{
                    background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                    borderRadius: '8px',
                    boxShadow: '0 4px 14px rgba(37,99,235,0.35)',
                    color: '#fff',
                    flexShrink: 0,
                    fontWeight: 700,
                    height: 40,
                    px: 2.5,
                    width: { xs: '100%', sm: 'auto' },
                    '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                  }}
                  variant="contained"
                >
                  {t('usermanage:addNewUser')}
                </Button>
              )}
            </Box>
          </Box>
        </Paper>

        {/* Table (desktop) / Cards (mobile) */}
        <Paper
          elevation={0}
          sx={{
            background: isMobile ? '#F1F5F9' : undefined,
            border: '1px solid #E2E8F0',
            borderRadius: 2,
            overflow: 'hidden',
          }}
        >
          {isMobile ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, p: 1.5 }}>
              {isLoading && (
                <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
                  <CircularProgress size={28} />
                </Box>
              )}
              {!isLoading && table.getRowModel().rows.length === 0 && (
                <Typography align="center" sx={{ color: '#64748B', py: 6 }}>
                  {t('common:noData')}
                </Typography>
              )}
              {!isLoading &&
                table.getRowModel().rows.map((row) => (
                  <UserCard
                    data={row.original}
                    handleDelete={handleDelete}
                    handleEdit={handleEdit}
                    handlePrivilegeData={handlePrivilegeData}
                    handleResetPassword={handleResetPassword}
                    key={row.id}
                    viewUserDetailsPopUp={viewUserDetailsPopUp}
                  />
                ))}
            </Box>
          ) : (
            <Box sx={{ maxWidth: '100%', minHeight: 480, overflow: 'auto' }}>
              <ReactTable isLoading={isLoading} {...(table as Table<object>)} />
            </Box>
          )}

          {table.getTotalSize() !== 0 && (
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          )}
        </Paper>

        {openAddUserManage && (
          <NewUserManage
            data={userManageData}
            handleCloseDialog={() => setOpenAddUserManage(false)}
            isImageEnabled={isImageEnabled}
            openModel={openAddUserManage}
            title={`${userManageData ? t('usermanage:edit') : t('usermanage:addNewUser')}`}
          />
        )}

        {openDeleteUserManage && (
          <DeletePopup
            content={`${t('usermanage:confirmMessage')} "${userManageNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteUserManage(false)}
            onConfirm={handleConfirmDelete}
            open={openDeleteUserManage}
            title={t('usermanage:deleteUserManage')}
          />
        )}

        {openUserManageResetPassword && (
          <ResetPasswordPopup
            handleCloseDialog={() => setOpenUserManageResetPassword(false)}
            openModel={openUserManageResetPassword}
            userId={userManageData?.id}
          />
        )}

        {openViewUser && userDetails && (
          <ViewUserDetails
            data={userDetails}
            open={openViewUser}
            setOpen={setOpenViewUser}
          />
        )}

        {userPrivilegeData && (
          <PrivilegesDialog
            data={userPrivilegeData}
            open={openPrivilege}
            setOpen={setOpenPrivilege}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default UserList;
