import React from 'react';
import {
  IUserDetailsData,
  IPrivileges,
} from '../../core/Interface/user.interface';
import { ColumnDef } from '@tanstack/react-table';
import { Box, Tooltip, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useTranslation } from 'react-i18next';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import LockResetIcon from '@mui/icons-material/LockReset';
import KeyIcon from '@mui/icons-material/Key';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';

const AVATAR_COLORS = [
  '#0F8B8D', '#2563EB', '#7c3aed', '#059669',
  '#D97706', '#DC2626', '#0891B2', '#4F46E5',
];

export const avatarColor = (name: string) => {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xff;
  return AVATAR_COLORS[h % AVATAR_COLORS.length];
};

export const ActionBtn = ({
  onClick, title, color, children, show = true, size = 30,
}: {
  onClick: () => void; title: string; color: string;
  children: React.ReactNode; show?: boolean; size?: number;
}) => {
  if (!show) return null;
  return (
    <Tooltip arrow title={title}>
      <Box
        onClick={(e) => { e.stopPropagation(); onClick(); }}
        sx={{
          alignItems: 'center',
          background: alpha(color, 0.1),
          border: `1px solid ${alpha(color, 0.22)}`,
          borderRadius: '7px',
          color,
          cursor: 'pointer',
          display: 'flex',
          height: size,
          justifyContent: 'center',
          transition: 'all 0.15s',
          width: size,
          '&:hover': { background: color, color: '#fff', transform: 'scale(1.07)' },
        }}
      >
        {children}
      </Box>
    </Tooltip>
  );
};

const useUserListColumn = ({
  handleEdit,
  handleDelete,
  handleResetPassword,
  viewUserDetailsPopUp,
  handlePrivilegeData,
}: {
  handleEdit: (data: IUserDetailsData) => void;
  handleDelete: (data: IUserDetailsData) => void;
  handleResetPassword: (data: IUserDetailsData) => void;
  viewUserDetailsPopUp?: (id: string) => void;
  handlePrivilegeData?: (data: IPrivileges[]) => void;
}) => {
  const { t } = useTranslation(['usermanage']);
  const { userHasRight } = useUser();

  return [
    {
      accessorKey: 'sn',
      header: '#',
      size: 52,
      cell: (cell) => (
        <Typography sx={{ color: alpha('#0F1D4D', 0.45), fontSize: 13, fontWeight: 600 }}>
          {cell.row.index + 1}
        </Typography>
      ),
    },
    {
      accessorKey: 'username',
      header: t('usermanage:title.username'),
      size: 180,
      cell: (cell) => {
        const name = (cell.getValue() as string) ?? '';
        const color = avatarColor(name);
        const initials = name.split(' ').slice(0, 2).map((w) => w[0]?.toUpperCase()).join('');
        return (
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.25 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: alpha(color, 0.12),
                border: `1px solid ${alpha(color, 0.22)}`,
                borderRadius: '8px',
                color,
                display: 'flex',
                flexShrink: 0,
                fontSize: 11,
                fontWeight: 800,
                height: 30,
                justifyContent: 'center',
                width: 30,
              }}
            >
              {initials || '?'}
            </Box>
            <Typography sx={{ color: '#0F1D4D', fontSize: 13, fontWeight: 600 }}>
              {name}
            </Typography>
          </Box>
        );
      },
    },
    {
      accessorKey: 'firstname',
      header: t('usermanage:title.firstname'),
      size: 160,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'lastname',
      header: t('usermanage:title.lastname'),
      size: 140,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'mobile',
      header: t('usermanage:title.mobile'),
      size: 130,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      id: 'branch',
      accessorFn: (row) => row.branch?.name ?? '',
      header: t('usermanage:title.branchName'),
      size: 160,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      id: 'actions',
      header: '',
      size: 150,
      cell: (cell) => {
        const data = cell.row.original;
        return (
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, justifyContent: 'flex-end' }}>
            <ActionBtn
              color="#0F8B8D"
              onClick={() => viewUserDetailsPopUp && viewUserDetailsPopUp(data.id)}
              title="View Details"
            >
              <FormatListBulletedIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#D97706"
              onClick={() => handleEdit(data)}
              show={userHasRight(Privileges.UserManageEdit)}
              title="Edit User"
            >
              <EditIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#DC2626"
              onClick={() => handleDelete(data)}
              show={userHasRight(Privileges.UserManageDelete)}
              title="Delete User"
            >
              <DeleteIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#64748B"
              onClick={() => handleResetPassword(data)}
              show={userHasRight(Privileges.UserManageEdit)}
              title="Reset Password"
            >
              <LockResetIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
            <ActionBtn
              color="#4F46E5"
              onClick={() => handlePrivilegeData && handlePrivilegeData(data.privileges)}
              show={userHasRight(Privileges.UserManageView)}
              title="User Privileges"
            >
              <KeyIcon sx={{ fontSize: 15 }} />
            </ActionBtn>
          </Box>
        );
      },
    },
  ] as ColumnDef<IUserDetailsData>[];
};

export default useUserListColumn;
