import React from 'react';
import { Box, Chip, Divider, Link, Paper, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import LockResetIcon from '@mui/icons-material/LockReset';
import KeyIcon from '@mui/icons-material/Key';
import PhoneIcon from '@mui/icons-material/Phone';
import StoreIcon from '@mui/icons-material/Store';
import {
  IUserDetailsData,
  IPrivileges,
} from '../../../core/Interface/user.interface';
import useUser from '../../../core/hooks/useUser';
import { Privileges } from '../../../core/types/commonType';
import { ActionBtn, avatarColor } from '../useUserListColumn';

interface IUserCard {
  data: IUserDetailsData;
  handleEdit: (data: IUserDetailsData) => void;
  handleDelete: (data: IUserDetailsData) => void;
  handleResetPassword: (data: IUserDetailsData) => void;
  viewUserDetailsPopUp: (id: string) => void;
  handlePrivilegeData: (data: IPrivileges[]) => void;
}

const UserCard = ({
  data,
  handleEdit,
  handleDelete,
  handleResetPassword,
  viewUserDetailsPopUp,
  handlePrivilegeData,
}: IUserCard) => {
  const { userHasRight } = useUser();
  const name = data.username ?? '';
  const color = avatarColor(name);
  const initials = name.split(' ').slice(0, 2).map((w) => w[0]?.toUpperCase()).join('');
  const fullName = [data.firstname, data.lastname].filter(Boolean).join(' ');
  const branchName = data.branch?.name;

  return (
    <Paper
      elevation={0}
      onClick={() => viewUserDetailsPopUp(data.id)}
      sx={{
        background: '#fff',
        border: '1px solid #CBD5E1',
        borderLeft: `4px solid ${color}`,
        borderRadius: 2,
        boxShadow: '0 2px 8px rgba(15,29,77,0.08)',
        cursor: 'pointer',
        overflow: 'hidden',
        '&:active': { background: '#F8FAFC' },
      }}
    >
      <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, p: 1.75 }}>
        <Box
          sx={{
            alignItems: 'center',
            background: alpha(color, 0.12),
            border: `1px solid ${alpha(color, 0.22)}`,
            borderRadius: '10px',
            color,
            display: 'flex',
            flexShrink: 0,
            fontSize: 13,
            fontWeight: 800,
            height: 42,
            justifyContent: 'center',
            width: 42,
          }}
        >
          {initials || '?'}
        </Box>
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography noWrap sx={{ color: '#0F1D4D', fontSize: 14, fontWeight: 700 }}>
            {name}
          </Typography>
          <Typography noWrap sx={{ color: '#64748B', fontSize: 12.5 }}>
            {fullName || '—'}
          </Typography>
        </Box>
        {branchName && (
          <Chip
            icon={<StoreIcon sx={{ fontSize: '14px !important' }} />}
            label={branchName}
            size="small"
            sx={{ fontSize: 11, fontWeight: 600, maxWidth: '40%' }}
            variant="outlined"
          />
        )}
      </Box>

      <Divider sx={{ borderColor: '#E2E8F0' }} />

      <Box
        sx={{
          alignItems: 'center',
          display: 'flex',
          gap: 1,
          justifyContent: 'space-between',
          background: '#F8FAFC',
          px: 1.75,
          py: 1.25,
        }}
      >
        {data.mobile ? (
          <Link
            href={`tel:${data.mobile}`}
            onClick={(e) => e.stopPropagation()}
            sx={{ alignItems: 'center', color: '#475569', display: 'inline-flex', fontSize: 13, gap: 0.5, minWidth: 0 }}
            underline="none"
          >
            <PhoneIcon sx={{ fontSize: 15 }} />
            {data.mobile}
          </Link>
        ) : (
          <Typography sx={{ color: '#94A3B8', fontSize: 13 }}>—</Typography>
        )}

        <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 0.75 }}>
          <ActionBtn
            color="#0F8B8D"
            onClick={() => viewUserDetailsPopUp(data.id)}
            size={34}
            title="View Details"
          >
            <FormatListBulletedIcon sx={{ fontSize: 17 }} />
          </ActionBtn>
          <ActionBtn
            color="#D97706"
            onClick={() => handleEdit(data)}
            show={userHasRight(Privileges.UserManageEdit)}
            size={34}
            title="Edit User"
          >
            <EditIcon sx={{ fontSize: 17 }} />
          </ActionBtn>
          <ActionBtn
            color="#DC2626"
            onClick={() => handleDelete(data)}
            show={userHasRight(Privileges.UserManageDelete)}
            size={34}
            title="Delete User"
          >
            <DeleteIcon sx={{ fontSize: 17 }} />
          </ActionBtn>
          <ActionBtn
            color="#64748B"
            onClick={() => handleResetPassword(data)}
            show={userHasRight(Privileges.UserManageEdit)}
            size={34}
            title="Reset Password"
          >
            <LockResetIcon sx={{ fontSize: 17 }} />
          </ActionBtn>
          <ActionBtn
            color="#4F46E5"
            onClick={() => handlePrivilegeData(data.privileges)}
            show={userHasRight(Privileges.UserManageView)}
            size={34}
            title="User Privileges"
          >
            <KeyIcon sx={{ fontSize: 17 }} />
          </ActionBtn>
        </Box>
      </Box>
    </Paper>
  );
};

export default React.memo(UserCard);
